import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createBenchmarkBundle } from '../scripts/benchmark-bundle.mjs';
import { run } from '../scripts/release-pack.mjs';

test('transfer bundle contains verified synthetic benchmark sources and works without installing dependencies', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'autorouter-benchmark-test-'));
  try {
    const archive = join(directory, 'benchmark.tar.gz');
    const created = await createBenchmarkBundle(archive);
    const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
    assert.equal(created.sha256, sha256(await readFile(archive)));
    assert.equal(await readFile(`${archive}.sha256`, 'utf8'), `${created.sha256}  benchmark.tar.gz\n`);
    const listing = (await run('tar', ['-tzf', archive])).stdout.split('\n').filter(Boolean);
    assert.ok(listing.every(path => path.startsWith('autorouter-benchmark/') && !path.includes('..')));
    assert.ok(listing.every(path => !/(?:^|\/)(?:\.env|\.git|node_modules|artifacts|config\.json|autorouter-session)/.test(path)));
    await run('tar', ['-xzf', archive, '-C', directory]);
    const root = join(directory, 'autorouter-benchmark');
    const manifest = JSON.parse(await readFile(join(root, 'source-manifest.json'), 'utf8'));
    assert.equal(manifest.schema_version, 1);
    assert.equal(created.files, Object.keys(manifest.files).length + 1);
    for (const [path, hash] of Object.entries(manifest.files)) assert.equal(sha256(await readFile(join(root, path))), hash, path);
    assert.equal(manifest.fixture_sha256, manifest.files['test/fixtures/ollama-routing.json']);
    const { stdout } = await run(process.execPath, ['scripts/evaluate-ollama.mjs', '--help'], { cwd: root });
    assert.match(stdout, /Does not download models or contact Claude\/Jev/);
    assert.match(stdout, /--timeout-ms 0 disables the warm timer/);
  } finally { await rm(directory, { recursive: true, force: true }); }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { LIVE_CASES, liveExpectedTier } from '../scripts/live-validation.mjs';
import { evaluateLiveCase, evaluateLiveReport } from '../src/evaluation-report.mjs';

test('all bundled live tasks declare rubric labels before provider invocation, including easy thinking follow-ups', () => {
  for (const [name, scenario] of Object.entries(LIVE_CASES)) {
    for (const [index, prompt] of scenario.prompts.entries()) {
      const body = { messages: scenario.prompts.slice(0, index).flatMap(content => [
        { role: 'user', content }, { role: 'assistant', content: 'Synthetic completed reply.' },
      ]).concat({ role: 'user', content: prompt }) };
      assert.ok(['haiku', 'sonnet', 'opus'].includes(liveExpectedTier(scenario, body)), name);
    }
  }
  assert.equal(liveExpectedTier(LIVE_CASES.thinking_continuation, { messages: [
    { role: 'user', content: LIVE_CASES.thinking_continuation.prompts[0] },
    { role: 'assistant', content: 'Synthetic reasoning.' },
    { role: 'user', content: LIVE_CASES.thinking_continuation.prompts[1] },
  ] }), 'haiku');
});

test('a live tier permutation cannot pass merely because aggregate tier coverage is complete', () => {
  const cases = ['haiku', 'sonnet', 'opus'].map((expected, index, tiers) => {
    const actual = tiers[(index + 1) % tiers.length];
    const routes = [{ request_class: 'main', source: 'jev', evaluator: 'jev', classified_tier: actual,
      expected_classified_tier: expected, model: `claude-${actual}-5` }];
    const accepted = evaluateLiveCase({ checks: { claude_success: true, expected_result: true }, routes, evaluator: 'jev' });
    assert.equal(accepted.gates.rubric.passed, false);
    return { ...accepted, routes };
  });
  const report = evaluateLiveReport(cases);
  assert.equal(report.gates.coverage.passed, true);
  assert.equal(report.passed, false);
  assert.equal(evaluateLiveCase({ checks: { claude_success: true, expected_result: true }, evaluator: 'jev',
    routes: [{ source: 'jev', classified_tier: 'haiku' }] }).gates.rubric.passed, false);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { setImmediate as nextTurn } from 'node:timers/promises';
import { readConfig } from '../src/config.mjs';
import { Router } from '../src/router.mjs';
import { createRouterServer, listen } from '../src/server.mjs';

const corpus = JSON.parse(await readFile(new URL('./fixtures/claude-protocol-v1.json', import.meta.url), 'utf8'));
const localToken = 'synthetic-protocol-local-token';
const identityHeaders = identity => Object.fromEntries(Object.entries(identity)
  .map(([name, value]) => [`x-claude-code-${name.replaceAll('_', '-')}`, value]));
function wire(response) {
  const ending = response.line_ending;
  return Buffer.from(response.prelude + response.events.map(event =>
    `event: ${event.type}${ending}data: ${JSON.stringify(event)}${ending}${ending}`).join(''));
}

test('protocol corpus versions synthetic examples separately from historical client evidence', () => {
  assert.equal(corpus.fixture_version, 1);
  assert.equal(corpus.synthetic, true);
  assert.match(corpus.reviewed_at, /^\d{4}-\d{2}-\d{2}$/);
  assert.match(corpus.description, /not captured traffic/);
  assert.match(corpus.limits.join(' '), /not evaluator quality or downstream task success/);
  assert.deepEqual([...new Set(corpus.historical_evidence.map(row => row.claude_version))], ['2.1.284', '2.1.285']);
  for (const evidence of corpus.historical_evidence) {
    assert.match(evidence.sha256, /^[a-f0-9]{64}$/);
    assert.match(evidence.artifact, /^artifacts\/[\w-]+\.json$/);
    if (evidence.observed_at !== null) assert.ok(Number.isFinite(Date.parse(evidence.observed_at)));
  }
  // This report has no recorded observation timestamp. Do not manufacture one
  // from a filesystem mtime or the date when the fixture corpus was authored.
  assert.equal(corpus.historical_evidence.find(row => row.kind === 'historical_synthetic_auto_permission_probe').observed_at, null);
  assert.deepEqual(corpus.official_contracts.map(row => row.area), ['messages', 'streaming', 'fallback', 'tool_search']);
  assert.ok(corpus.official_contracts.every(row => new URL(row.url).origin === 'https://platform.claude.com'));
  assert.equal(new Set(corpus.cases.map(row => row.id)).size, corpus.cases.length);
  const coverage = new Set(corpus.cases.flatMap(row => row.covers));
  for (const required of ['haiku_floor', 'opus', 'thinking', 'deferred_tools', 'compaction', 'goal_feedback',
    'agent_scope', 'auxiliary_verdict', 'provider_fallback', 'mixed_usage', 'incomplete_response']) assert.ok(coverage.has(required), required);
  for (const scenario of corpus.cases) for (const step of scenario.steps) {
    assert.ok(step.request && step.response && step.expected);
    assert.ok(step.evaluator_tier === null || ['haiku', 'sonnet', 'opus'].includes(step.evaluator_tier));
    assert.deepEqual(Object.keys(step.expected_request_overrides).filter(key => !['model', 'thinking'].includes(key)), []);
    // Newly authored examples must not invent provider-signed history.
    assert.ok(!JSON.stringify(step.request).includes('"signature"'));
  }
});

async function fixtureGateway(t, scenario) {
  const received = [], records = [], statuses = [], failures = [];
  let activeStep, evaluations = 0;
  const upstream = http.createServer(async (req, res) => {
    try {
      const chunks = [];
      for await (const chunk of req) chunks.push(chunk);
      received.push({ body: JSON.parse(Buffer.concat(chunks).toString('utf8')), headers: req.headers, path: req.url });
      const bytes = wire(activeStep.response);
      res.writeHead(200, { 'content-type': activeStep.response.content_type, 'request-id': `synthetic-${activeStep.id}` });
      // Split a frame header and, where present, a multibyte code point. The
      // observer must preserve the original CRLF, comments and response bytes.
      const multibyte = bytes.indexOf(Buffer.from('😀'));
      const boundaries = [1, 19, ...(multibyte > 19 ? [multibyte + 1] : [])];
      let start = 0;
      for (const end of boundaries) { res.write(bytes.subarray(start, end)); start = end; await nextTurn(); }
      res.end(bytes.subarray(start));
    } catch (error) { failures.push(error); res.writeHead(500); res.end('Synthetic fixture failed.'); }
  });
  t.after(() => { upstream.closeAllConnections(); upstream.close(); });
  const upstreamAddress = await listen(upstream, 0);
  const config = { ...readConfig({ AUTOROUTER_EVALUATOR: 'jev',
    ANTHROPIC_API_KEY: 'synthetic-upstream-key', TYPESAFE_API_KEY: 'synthetic-evaluator-key',
    AUTOROUTER_CLIENT_PROFILE: scenario.profile,
    AUTOROUTER_HAIKU_MODEL: corpus.models.haiku, AUTOROUTER_SONNET_MODEL: corpus.models.sonnet,
    AUTOROUTER_OPUS_MODEL: corpus.models.opus,
  }), localToken, sessionLogMode: 'metadata', upstream: `http://127.0.0.1:${upstreamAddress.port}` };
  const router = new Router(config, { fetchImpl: async url => {
    assert.equal(url, config.jevEndpoint);
    assert.notEqual(activeStep.evaluator_tier, null, 'Auxiliary verdict requests must bypass the evaluator');
    evaluations++;
    return Response.json({ answers: { tier: { choice: activeStep.evaluator_tier, confidence: 0.99 } } });
  } });
  const server = createRouterServer(config, { router, tokenCounter: () => assert.fail('Small fixtures do not require token counting'),
    log: () => {}, onStatus: entry => statuses.push(entry), onRecord: entry => records.push(entry) });
  t.after(() => { server.closeAllConnections(); server.close(); });
  const address = await listen(server, 0);
  return { received, records, statuses, failures, router, evaluations: () => evaluations,
    send: async step => {
      activeStep = step;
      return fetch(`http://127.0.0.1:${address.port}/v1/messages?beta=true`, { method: 'POST',
        headers: { 'x-api-key': localToken, 'content-type': 'application/json',
          'anthropic-beta': 'synthetic-protocol-contract', 'anthropic-version': '2023-06-01', ...identityHeaders(step.identity) },
        body: JSON.stringify(step.request) });
    } };
}

for (const scenario of corpus.cases) test(`protocol v1: ${scenario.id}`, { timeout: 10000 }, async t => {
  const original = structuredClone(scenario);
  const gateway = await fixtureGateway(t, scenario);
  for (const [index, step] of scenario.steps.entries()) {
    const before = gateway.evaluations();
    const response = await gateway.send(step);
    assert.equal(response.status, 200, step.id);
    assert.equal(response.headers.get('request-id'), `synthetic-${step.id}`);
    assert.deepEqual(Buffer.from(await response.arrayBuffer()), wire(step.response), `${step.id}: response bytes`);
    for (let tries = 0; gateway.records.length < (index + 1) * 2 && tries < 100; tries++) await nextTurn();
    assert.deepEqual(gateway.failures, []);
    assert.equal(gateway.evaluations() - before, step.evaluator_tier === null ? 0 : 1, `${step.id}: evaluator calls`);
    const upstream = gateway.received[index];
    assert.deepEqual(upstream.body, { ...step.request, ...step.expected_request_overrides }, `${step.id}: only declared request adaptations`);
    assert.equal(upstream.path, '/v1/messages?beta=true');
    assert.equal(upstream.headers['anthropic-beta'], 'synthetic-protocol-contract');
    assert.equal(upstream.headers['anthropic-version'], '2023-06-01');
    assert.equal(upstream.headers['x-api-key'], 'synthetic-upstream-key');
    for (const [name, value] of Object.entries(identityHeaders(step.identity))) assert.equal(upstream.headers[name], value);
    const pair = gateway.records.slice(index * 2, index * 2 + 2);
    assert.deepEqual(pair.map(row => row.event), ['decision', 'outcome']);
    const [decision, outcome] = pair;
    assert.equal(decision.schema_version, 2);
    assert.equal(outcome.request_id, decision.request_id);
    for (const [field, value] of Object.entries(step.identity)) {
      assert.equal(decision[field], value);
      assert.equal(outcome[field], value);
    }
    for (const field of ['selected_model', 'source', 'reason', 'compatibility_reason']) assert.equal(decision[field], step.expected[field], `${step.id}: ${field}`);
    assert.equal(decision.classified_tier, step.evaluator_tier ?? undefined);
    assert.equal(outcome.status, 'completed');
    for (const field of ['confirmed_model', 'completion_confirmed', 'usage_complete', 'pricing_eligible', 'unpriced_reason', 'continuity_state']) {
      assert.equal(outcome[field], step.expected[field], `${step.id}: ${field}`);
    }
    assert.deepEqual(outcome.model_transitions, step.expected.model_transitions ?? [step.expected.confirmed_model]);
    if (step.expected.usage_complete) {
      assert.equal(outcome.usage.input_tokens, 100);
      assert.equal(outcome.usage.output_tokens, 12);
      assert.equal(outcome.usage.cache_read_input_tokens, 20);
    }
    assert.ok(!Object.hasOwn(decision, 'prompt_excerpt'));
    assert.ok(!JSON.stringify(pair).includes('synthetic-evaluator-key'));
    assert.equal(gateway.router.turns.attempts.size, 0, `${step.id}: no unfinished routing attempt`);
  }
  assert.deepEqual(scenario, original, 'Fixtures and request bodies must remain immutable');
  assert.equal(new Set(gateway.records.filter(row => row.event === 'decision').map(row => row.request_id)).size, scenario.steps.length);
});

#!/usr/bin/env node
import { createHash } from 'node:crypto';
import { lstat, mkdir, mkdtemp, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { basename, dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { run } from './release-pack.mjs';

// Explicit source allowlist: never copy configuration, logs, credentials,
// node_modules, git metadata or private benchmark results to another host.
export async function createBenchmarkBundle(destination) {
  const root = fileURLToPath(new URL('../', import.meta.url));
  const temporary = await mkdtemp(join(tmpdir(), 'autorouter-benchmark-bundle-'));
  const parent = join(temporary, 'autorouter-benchmark');
  try {
    const paths = ['package.json', 'scripts/evaluate-ollama.mjs', 'docs/hardware-benchmark.md', 'docs/hardware-results-16gb.md',
      'docs/hardware-results-16gb.json', 'test/fixtures/ollama-routing.json',
      ...(await readdir(join(root, 'src'))).filter(name => /^[A-Za-z0-9_-]+\.mjs$/.test(name)).map(name => `src/${name}`)];
    const sources = {};
    for (const path of paths) {
      const input = join(root, path), target = join(parent, path);
      const info = await lstat(input);
      if (!info.isFile() || info.isSymbolicLink() || info.size > 1024 * 1024) throw new Error('Benchmark source must be a bounded regular file.');
      const bytes = await readFile(input);
      sources[path] = createHash('sha256').update(bytes).digest('hex');
      await mkdir(dirname(target), { recursive: true });
      await writeFile(target, bytes);
    }
    await writeFile(join(parent, 'source-manifest.json'), `${JSON.stringify({ schema_version: 1,
      fixture_sha256: sources['test/fixtures/ollama-routing.json'], files: sources }, null, 2)}\n`);
    await mkdir(dirname(destination), { recursive: true });
    await run('tar', ['-czf', resolve(destination), '-C', temporary, 'autorouter-benchmark']);
    const checksum = createHash('sha256').update(await readFile(destination)).digest('hex');
    await writeFile(`${destination}.sha256`, `${checksum}  ${basename(destination)}\n`);
    return { bundle: resolve(destination), sha256: checksum, files: paths.length + 1 };
  } finally { await rm(temporary, { recursive: true, force: true }); }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length > 3) throw new Error('Usage: node scripts/benchmark-bundle.mjs [destination.tar.gz]');
  const report = await createBenchmarkBundle(resolve(process.argv[2] ?? 'artifacts/autorouter-hardware-benchmark.tar.gz'));
  console.log(JSON.stringify(report, null, 2));
}

#!/usr/bin/env node
// Live subscription validation: prompts and credentials stay out of the report.
import { spawn } from 'node:child_process';
import { randomBytes, createHash } from 'node:crypto';
import { mkdtemp, writeFile, readFile, realpath, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { readConfig, requireKeys } from '../src/config.mjs';
import { buildClaudeEnv } from '../src/auth.mjs';
import { Router, buildState, contextSizeBytes } from '../src/router.mjs';
import { createRouterServer, listen } from '../src/server.mjs';
import { createStatusState } from '../src/status-state.mjs';
import { renderStatusLine } from '../src/statusline.mjs';
import { createEvaluationPolicy, evaluateLiveCase, evaluateLiveReport, modelTier, profileTier } from '../src/evaluation-report.mjs';

const TEST_SOURCE = `import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mergeIntervals } from './merge-intervals.mjs';
test('sorts, merges nested and touching intervals, and preserves the input', () => {
  const input = [[8, 10], [1, 5], [2, 3], [5, 7], [12, 15], [9, 11]];
  const original = structuredClone(input);
  assert.deepEqual(mergeIntervals(input), [[1, 7], [8, 11], [12, 15]]);
  assert.deepEqual(input, original);
});
test('empty, negative, nested and duplicate intervals', () => {
  assert.deepEqual(mergeIntervals([]), []);
  assert.deepEqual(mergeIntervals([[1, 9], [2, 3], [4, 5], [1, 9]]), [[1, 9]]);
  assert.deepEqual(mergeIntervals([[-2, 1], [-5, -3], [-3, -2]]), [[-5, 1]]);
});
`;
const IMPLEMENTATION = `export function mergeIntervals(intervals) {
  const merged = [];
  for (const [start, end] of intervals) {
    const previous = merged.at(-1);
    if (previous && start <= previous[1]) previous[1] = end;
    else merged.push([start, end]);
  }
  return merged;
}
`;
// Keep this opt-in: it deliberately sends over 200K input tokens to reproduce
// a simple task whose system context exceeds Haiku's window. A file avoids the
// platform's process-argument limit, and the fixture is removed after the run.
const LARGE_CONTEXT_SYSTEM = 'This is a synthetic context-capacity validation fixture. The repeated words between the padding markers are irrelevant data. Answer the user normally and do not repeat the padding.\n<synthetic-padding>\n'
  + 'x '.repeat(220000) + '\n</synthetic-padding>\n';
const SYNTHETIC_REMINDER = '<system-reminder>\nSynthetic tool catalog metadata, unrelated to the user task.\n'
  + 'Synthetic catalog entry for a tool that is not enabled. '.repeat(4000) + '\n</system-reminder>';
const CASES = {
  simple: {
    expectedClassifiedTier: 'haiku',
    prompts: ['What does the JavaScript expression [].length evaluate to? Reply with only the integer.'],
    check: results => results.length === 1 && results[0].trim() === '0',
  },
  medium: {
    expectedClassifiedTier: 'sonnet',
    prompts: ['Review this JavaScript event-loop sequence and determine the output order: console.log("A"); Promise.resolve().then(() => { console.log("B"); queueMicrotask(() => console.log("C")); }); console.log("D"); Explain the ordering briefly, then finish with ORDER=A,D,B,C if that is correct, or ORDER= followed by the actual comma-separated order.'],
    check: results => results.length === 1 && /ORDER=A,D,B,C/.test(results[0]),
  },
  difficult: {
    expectedClassifiedTier: 'opus',
    prompts: ['Analyze a distributed locking design rigorously. A and B use a lease service with monotonically increasing fencing tokens. A obtains token 10 and starts a write, then pauses longer than its lease. B obtains token 11, writes the resource, and returns success. A resumes with token 10. The database validates only that the token was once issued by the lease service; it does not remember the largest token observed. Can the design guarantee that A cannot overwrite B? Give a concrete legal schedule, distinguish fencing from mere lease validity, and explain the minimum atomic resource-side check and state needed to repair it, including duplicate retries. Finish with exactly one verdict line: VERDICT=SAFE or VERDICT=UNSAFE.'],
    check: results => results.length === 1 && /VERDICT=UNSAFE/.test(results[0]) && /atomic/i.test(results[0]) && /10/.test(results[0]) && /11/.test(results[0]),
  },
  coding: {
    expectedClassifiedTier: 'sonnet',
    tools: true,
    prompts: ['In this synthetic fixture, repair mergeIntervals in merge-intervals.mjs so that it sorts and merges overlapping or touching numeric intervals, handles nested intervals, and never changes the input. Use Read to inspect the source and its test, Edit to fix only merge-intervals.mjs, and Bash to execute exactly: node --test merge-intervals.test.mjs. Do not change tests or any other files. After tests pass, summarize the fix briefly.'],
    check: results => results.length === 1 && results[0].length > 0,
  },
  continuation: {
    expectedClassifiedTier: 'haiku',
    prompts: [
      'Remember this synthetic test marker for our next message: ROUTER_CONTINUATION_47. Reply exactly ACK.',
      'What was the synthetic test marker I asked you to remember? Reply with only that marker.',
    ],
    check: results => results.length === 2 && results[0].trim() === 'ACK' && results[1].trim() === 'ROUTER_CONTINUATION_47',
  },
  large_context: {
    expectedClassifiedTier: 'haiku',
    optIn: true,
    appendSystemPrompt: LARGE_CONTEXT_SYSTEM,
    prompts: ['What does the JavaScript expression [].length evaluate to? Reply with only the integer.'],
    check: results => results.length === 1 && results[0].trim() === '0',
  },
  example_haiku: {
    optIn: true, syntheticReminder: true, expectedTier: 'haiku',
    prompts: ['What does the JavaScript expression `[].length` evaluate to? Reply with only the integer.'],
    check: results => results.length === 1 && results[0].trim() === '0',
  },
  example_sonnet: {
    optIn: true, syntheticReminder: true, expectedTier: 'sonnet',
    prompts: ['Add pagination to this REST endpoint using `page` and `pageSize`. Validate the parameters, preserve existing filtering, and add tests for empty results and out-of-range pages.'],
    check: results => results.length === 1 && results[0].length > 0,
  },
  example_opus: {
    optIn: true, syntheticReminder: true, expectedTier: 'opus',
    prompts: ['Review this distributed locking design: worker A’s lease expires while paused. Worker B acquires a newer fencing token and writes successfully. A resumes and writes using its old token. The database checks only whether a token was ever issued. Explain the failure sequence and design the minimum atomic database check that prevents stale writes, including duplicate retries.'],
    check: results => results.length === 1 && /atomic/i.test(results[0]),
  },
};
CASES.thinking_continuation = {
  expectedClassifiedTiers: ['opus', 'haiku'],
  prompts: [
    `${CASES.difficult.prompts[0]} Also remember the synthetic marker ROUTER_THINKING_83 for my next message. Keep your analysis concise.`,
    'What was the synthetic marker in my previous message? Reply with only that marker.',
  ],
  check: results => results.length === 2 && /VERDICT=UNSAFE/.test(results[0]) && results[1].trim() === 'ROUTER_THINKING_83',
};

export const LIVE_CASES = Object.freeze(CASES);
export function liveExpectedTier(scenario, body) {
  if (!scenario.expectedClassifiedTiers) return scenario.expectedClassifiedTier ?? scenario.expectedTier;
  const current = buildState(body).current_task;
  const index = scenario.prompts.findIndex(prompt => current === prompt);
  return scenario.expectedClassifiedTiers[index];
}

function parseArgs(args) {
  const options = { cases: Object.keys(CASES).filter(name => !CASES[name].optIn), timeoutMs: 120000, model: undefined };
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--help') { options.help = true; continue; }
    if (arg === '--no-thinking') { options.noThinking = true; continue; }
    if (['--simulate-evaluator-outage', '--simulate-jev-outage'].includes(arg)) { options.simulateJevOutage = true; continue; }
    if (!['--case', '--timeout-ms', '--model', '--client-model'].includes(arg) || !args[i + 1]) throw new Error('Use --help for supported options');
    const value = args[++i];
    if (arg === '--case') { options.cases = value.split(','); options.selectedCases = true; }
    if (arg === '--model' || arg === '--client-model') options.model = value;
    if (arg === '--timeout-ms') options.timeoutMs = Number(value);
  }
  if (options.cases.some(name => !CASES[name])) throw new Error('Unknown live-test case');
  if (!Number.isInteger(options.timeoutMs) || options.timeoutMs < 1000 || options.timeoutMs > 120000) throw new Error('--timeout-ms must be an integer between 1000 and 120000');
  return options;
}

const family = model => /haiku/i.test(model) ? 'haiku' : /sonnet/i.test(model) ? 'sonnet' : /opus/i.test(model) ? 'opus' : model;
const digest = text => createHash('sha256').update(text).digest('hex');

function metadata(body, context) {
  const blocks = body.messages.flatMap(message => Array.isArray(message.content) ? message.content : []);
  return {
    requested_model: body.model,
    request_class: ['main', 'compaction', 'auxiliary'].includes(context.requestClass) ? context.requestClass : context.requestClass ? 'other' : 'unspecified',
    message_count: body.messages.length,
    message_roles: body.messages.map(message => message.role),
    request_bytes: Buffer.byteLength(JSON.stringify(body)),
    system_bytes: Buffer.byteLength(JSON.stringify(body.system ?? null)),
    tools_bytes: Buffer.byteLength(JSON.stringify(body.tools ?? [])),
    messages_bytes: Buffer.byteLength(JSON.stringify(body.messages)),
    has_system_messages: body.messages.some(message => message.role === 'system'),
    thinking_type: ['enabled', 'adaptive', 'disabled'].includes(body.thinking?.type) ? body.thinking.type : 'unspecified',
    thinking_history_count: blocks.filter(block => ['thinking', 'redacted_thinking'].includes(block.type)).length,
    tool_result_count: blocks.filter(block => block.type === 'tool_result').length,
    tool_count: body.tools?.length ?? 0,
    typed_tools: [...new Set((body.tools ?? []).map(tool => tool.type).filter(Boolean))],
    max_tokens: body.max_tokens,
    has_output_effort: Boolean(body.output_config?.effort),
    has_context_management: Boolean(body.context_management),
  };
}

function runClaude({ cwd, env, prompts, timeoutMs, model, tools, maxTurnsSupported, appendSystemPromptFile }) {
  const args = [
    '--print', '--safe-mode', '--restricted', '--setting-sources', '',
    '--strict-mcp-config', '--mcp-config', '{"mcpServers":{}}',
    '--no-session-persistence', '--input-format', 'stream-json',
    '--output-format', 'stream-json', '--verbose', '--permission-mode', 'dontAsk',
    '--no-chrome', '--tools', tools ? 'Read,Edit,Bash' : '',
  ];
  if (maxTurnsSupported) args.push('--max-turns', '12');
  if (model) args.push('--model', model);
  if (appendSystemPromptFile) args.push('--append-system-prompt-file', appendSystemPromptFile);
  // A single leading slash is relative to the permission settings source,
  // not the filesystem root. Anchor the edit to this isolated working dir.
  if (tools) args.push('--allowedTools', 'Read', 'Edit(./merge-intervals.mjs)', 'Bash(node --test merge-intervals.test.mjs)');
  return new Promise(resolve => {
    const started = performance.now();
    const child = spawn('claude', args, { cwd, env, stdio: ['pipe', 'pipe', 'pipe'] });
    const results = [], assistantModels = new Set(), toolNames = new Set(), modelUsage = {}, failures = [], usageShapes = [];
    const calls = new Map(), toolResults = new Map(), denials = [];
    let buffer = '', resultCount = 0, bytes = 0, stderrBytes = 0, timedOut = false, killedForOutput = false;
    let deniedTools = 0, parseErrors = 0, sentPrompts = 0, killTimer;
    const stop = () => { child.kill('SIGTERM'); killTimer = setTimeout(() => child.kill('SIGKILL'), 2000); killTimer.unref(); };
    const timeout = setTimeout(() => { timedOut = true; stop(); }, timeoutMs);
    function sendNext() {
      if (sentPrompts >= prompts.length) { child.stdin.end(); return; }
      child.stdin.write(`${JSON.stringify({ type: 'user', message: { role: 'user', content: prompts[sentPrompts++] } })}\n`);
    }
    child.stdin.on('error', () => {});
    function callMetadata(name, input = {}) {
      const tool = ['Read', 'Edit', 'Bash'].includes(name) ? name : 'other';
      if (tool === 'Bash') {
        const command = String(input.command ?? '').trim();
        return { tool, command_category: command === 'pwd' ? 'working_directory_lookup' : command === 'node --test merge-intervals.test.mjs' ? 'exact_fixture_test'
          : command.includes('node --test merge-intervals.test.mjs') ? 'fixture_test_with_other_shell_text' : 'other' };
      }
      const path = String(input.file_path ?? '');
      return { tool, target_category: path === 'merge-intervals.mjs' || path === './merge-intervals.mjs' || path === join(cwd, 'merge-intervals.mjs') ? 'fixture_source'
        : path === 'merge-intervals.test.mjs' || path === './merge-intervals.test.mjs' || path === join(cwd, 'merge-intervals.test.mjs') ? 'fixture_test' : 'other' };
    }
    function event(line) {
      if (!line.trim()) return;
      let value;
      try { value = JSON.parse(line); } catch { parseErrors++; return; }
      if (value.type === 'assistant') {
        if (typeof value.message?.model === 'string') assistantModels.add(value.message.model);
        const usage = value.message?.usage;
        if (usage && typeof usage === 'object') {
          const safeEnum = value => value === null ? null : value === undefined ? 'absent'
            : ['global', 'us', 'not_available', 'standard', 'message', 'compaction', 'advisor_message', 'fallback_message'].includes(value) ? value : 'other';
          usageShapes.push({ inference_geo: safeEnum(usage.inference_geo),
            iterations: Array.isArray(usage.iterations) ? usage.iterations.slice(0, 10).map(entry => ({
              type: safeEnum(entry?.type),
              ...Object.fromEntries(['input_tokens', 'output_tokens', 'cache_creation_input_tokens', 'cache_read_input_tokens']
                .filter(key => Number.isSafeInteger(entry?.[key])).map(key => [key, entry[key]])),
            })) : usage.iterations === null ? null : 'absent' });
        }
        for (const block of value.message?.content ?? []) if (block.type === 'tool_use') {
          if (['Read', 'Edit', 'Bash'].includes(block.name)) toolNames.add(block.name);
          calls.set(block.id, callMetadata(block.name, block.input));
        }
      }
      if (value.type === 'user') {
        for (const block of value.message?.content ?? []) if (block.type === 'tool_result') {
          toolResults.set(block.tool_use_id, { is_error: Boolean(block.is_error) });
        }
      }
      if (value.type === 'result') {
        resultCount++;
        results.push(typeof value.result === 'string' ? value.result : '');
        if (value.is_error) failures.push(['error_max_turns', 'error_during_execution', 'error_max_budget_usd'].includes(value.subtype) ? value.subtype : 'claude_result_error');
        deniedTools += value.permission_denials?.length ?? 0;
        for (const denial of value.permission_denials ?? []) {
          denials.push({ id: denial.tool_use_id, ...callMetadata(denial.tool_name, denial.tool_input) });
        }
        for (const [name, usage] of Object.entries(value.modelUsage ?? {})) {
          modelUsage[name] = Object.fromEntries(Object.entries(usage).filter(([key, val]) => /tokens|cost|requests/i.test(key) && typeof val === 'number'));
        }
        if (sentPrompts < prompts.length && !value.is_error) sendNext();
        else child.stdin.end();
      }
    }
    child.stdout.on('data', chunk => {
      bytes += chunk.length;
      if (bytes > 8 * 1024 * 1024) { killedForOutput = true; stop(); return; }
      buffer += chunk.toString();
      let end;
      while ((end = buffer.indexOf('\n')) >= 0) { event(buffer.slice(0, end)); buffer = buffer.slice(end + 1); }
    });
    child.stderr.on('data', chunk => { stderrBytes += chunk.length; });
    child.on('error', () => failures.push('claude_spawn_error'));
    child.on('close', (code, signal) => {
      clearTimeout(timeout); clearTimeout(killTimer);
      if (buffer.trim()) event(buffer);
      const outcomes = [...calls].map(([id, call]) => ({ ...call,
        result_received: toolResults.has(id), is_error: toolResults.get(id)?.is_error ?? null,
        permission_denied: denials.some(denial => denial.id === id),
      }));
      resolve({ results, exit_code: code, exit_signal: signal, timed_out: timedOut, output_limit_exceeded: killedForOutput,
        duration_ms: Math.round(performance.now() - started), result_count: resultCount, assistant_models: [...assistantModels],
        tools_used: [...toolNames], permission_denials: deniedTools, parse_errors: parseErrors,
        stderr_bytes: stderrBytes, failures, tool_outcomes: outcomes, provider_usage_shapes: usageShapes,
        successful_tools: [...new Set(outcomes.filter(outcome => outcome.result_received && !outcome.is_error && !outcome.permission_denied).map(outcome => outcome.tool))],
        denied_tool_details: denials.map(({ id, ...detail }) => detail), client_model_usage_estimate: modelUsage });
    });
    sendNext();
  });
}

function runCommand(command, args, cwd, timeoutMs = 10000) {
  return new Promise(resolve => {
    const child = spawn(command, args, { cwd, stdio: ['ignore', 'pipe', 'ignore'] });
    let stdout = '', overflow = false;
    const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
    child.stdout.on('data', chunk => { if (stdout.length < 100000) stdout += chunk.toString(); else { overflow = true; child.kill('SIGKILL'); } });
    child.on('error', () => {});
    child.on('close', code => { clearTimeout(timer); resolve({ code, stdout, overflow }); });
  });
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  if (options.help) {
    console.log('Usage: node --env-file=.env scripts/live-validation.mjs [--case simple,medium,difficult,coding,continuation,thinking_continuation,large_context,example_haiku,example_sonnet,example_opus] [--client-model MODEL] [--no-thinking] [--simulate-evaluator-outage] [--timeout-ms 120000]\nUses the existing Claude subscription login. Executes real Claude requests and the configured evaluator (except simulated evaluator outages). --simulate-jev-outage remains an alias. Normal runs require successful evaluation without fallback; outage runs require fallback. Full compatible runs require Haiku/Sonnet/Opus coverage, Auto runs require Sonnet/Opus; explicit case subsets require only their declared tiers. Reports separate transport, evaluator, rubric, policy and task gates. Reports metadata only; fixtures are removed. Model costs in CLI usage are list-price estimates, not subscription charges.\nlarge_context is opt-in and deliberately sends more than 200K input tokens in a synthetic system fixture. example_* cases reproduce reminder-prefixed prompts with synthetic context.');
    return;
  }
  const config = readConfig({ ...process.env, AUTOROUTER_AUTH_MODE: 'subscription', AUTOROUTER_TOKEN: randomBytes(32).toString('hex') });
  const requiredTiers = options.selectedCases ? [...new Set(options.cases.map(name =>
    profileTier(CASES[name].expectedTier ?? (name === 'large_context' ? 'sonnet' : undefined), config.clientProfile)).filter(Boolean))] : undefined;
  const qualityPolicy = createEvaluationPolicy({ profile: config.clientProfile, requiredTiers });
  requireKeys(config);
  const help = await runCommand('claude', ['--help'], process.cwd());
  if (help.code !== 0 || !help.stdout.includes('--safe-mode') || !help.stdout.includes('--restricted')) throw new Error('A Claude CLI with --safe-mode and --restricted support is required');
  const maxTurnsSupported = help.stdout.includes('--max-turns');
  const version = await runCommand('claude', ['--version'], process.cwd());
  const report = { type: 'live_validation', cli_version: version.stdout.trim().slice(0, 100), auth_mode: 'subscription',
    fixture_version: 1, fixture_sha256: digest(JSON.stringify(Object.entries(CASES).map(([name, item]) => ({ name,
      prompts: item.prompts, expected: item.expectedClassifiedTiers ?? item.expectedClassifiedTier ?? item.expectedTier })))),
    evaluator: config.evaluator, classifier_timeout_ms: config.evaluator === 'ollama' ? config.ollamaTimeoutMs : config.jevTimeoutMs, client_profile: config.clientProfile,
    client_model: options.model ?? (config.clientProfile === 'compatible' ? config.models.haiku : process.env.ANTHROPIC_MODEL ?? 'default'),
    thinking_disabled: Boolean(options.noThinking || config.clientProfile === 'compatible' || process.env.MAX_THINKING_TOKENS === '0'),
    simulated_classifier_outage: options.simulateJevOutage ?? false,
    quality_policy: qualityPolicy, coverage_scope: options.selectedCases ? 'selected_cases' : 'full_profile',
    cost_basis: 'CLI list-price estimate, not subscription charges', max_turns_supported: maxTurnsSupported, cases: [] };
  const root = await mkdtemp(join(tmpdir(), 'autorouter-live-'));
  try {
    for (const name of options.cases) {
      const dir = await realpath(await mkdtemp(join(root, `${name}-`)));
      const scenario = CASES[name];
      let appendSystemPromptFile;
      if (scenario.appendSystemPrompt) {
        appendSystemPromptFile = join(dir, 'synthetic-system-context.txt');
        await writeFile(appendSystemPromptFile, scenario.appendSystemPrompt, { mode: 0o600 });
      }
      if (scenario.tools) {
        await writeFile(join(dir, 'merge-intervals.mjs'), IMPLEMENTATION);
        await writeFile(join(dir, 'merge-intervals.test.mjs'), TEST_SOURCE);
      }
      const routes = [], proxyErrors = [], upstreamModels = new Set(), upstreamStatuses = [], usageReports = [];
      const observations = new Map();
      const statusState = createStatusState({ baselineModel: config.models.opus, directory: root });
      await statusState.ready;
      const actualRouter = new Router(config, options.simulateJevOutage ? { fetchImpl: async () => { throw new TypeError('simulated_classifier_outage'); } } : {});
      const router = { complete: (requestId, evidence) => actualRouter.complete(requestId, evidence), async route(body, context) {
        if (scenario.syntheticReminder && !['compaction', 'auxiliary'].includes(context.requestClass)) {
          const first = body.messages.find(message => message.role === 'user');
          const content = typeof first.content === 'string' ? [{ type: 'text', text: first.content }] : first.content;
          first.content = [{ type: 'text', text: SYNTHETIC_REMINDER }, ...content];
        }
        const evidence = metadata(body, context);
        evidence.expected_classified_tier = liveExpectedTier(scenario, body);
        if (scenario.syntheticReminder) {
          evidence.context_guard_bytes = contextSizeBytes(body);
          evidence.classifier_contains_example = JSON.stringify(buildState(body)).includes(JSON.stringify(scenario.prompts[0]).slice(1, -1));
        }
        const decision = await actualRouter.route(body, context);
        routes.push({ ...evidence, ...decision });
        return decision;
      } };
      const server = createRouterServer(config, { router, onStatus: entry => {
        statusState.update(entry);
        if (entry.event === 'upstream_usage') usageReports.push(entry.usage);
        if (entry.request_id) {
          const observed = observations.get(entry.request_id) ?? { request_id: entry.request_id };
          if (entry.event === 'route') Object.assign(observed, { requested_model: entry.requested_model,
            classified_tier: entry.classified_tier ?? null, selected_model: entry.model, confirmed_model: null, source: entry.source });
          if (entry.event === 'upstream_model') observed.confirmed_model = entry.model;
          if (entry.event === 'upstream_response') observed.http_status = entry.status;
          if (['request_complete', 'request_error', 'request_cancelled'].includes(entry.event)) observed.outcome = entry.event;
          observations.set(entry.request_id, observed);
        }
      }, log: entry => {
        if (entry.event === 'upstream_model' && typeof entry.model === 'string') upstreamModels.add(entry.model);
        if (entry.event === 'upstream_response') upstreamStatuses.push(entry.status);
        if (['proxy_error', 'invalid_request_shape'].includes(entry.event)) proxyErrors.push({ event: entry.event, status: entry.status });
      } });
      let run, statusSnapshot;
      try {
        const address = await listen(server, 0);
        const env = buildClaudeEnv(config, `http://127.0.0.1:${address.port}`);
        if (options.noThinking) env.MAX_THINKING_TOKENS = '0';
        run = await runClaude({ cwd: dir, env,
          ...scenario, timeoutMs: options.timeoutMs, model: options.model, maxTurnsSupported, appendSystemPromptFile });
      } finally {
        server.closeAllConnections();
        await new Promise(resolve => server.close(resolve));
        try {
          await statusState.flush();
          if (statusState.path) statusSnapshot = JSON.parse(await readFile(statusState.path, 'utf8'));
        } finally { await statusState.close(); }
      }
      const checks = {
        claude_success: run.exit_code === 0 && !run.timed_out && !run.output_limit_exceeded && run.failures.length === 0,
        expected_result: scenario.check(run.results),
        requests_reached_router: routes.length > 0,
        // Claude's assistant and modelUsage fields can retain its requested
        // model. The server observes the actual upstream response model.
        upstream_model_evidence: observations.size > 0 && [...observations.values()].every(row =>
          modelTier(row.confirmed_model) && modelTier(row.confirmed_model) === modelTier(row.selected_model)),
        no_upstream_api_errors: upstreamStatuses.length > 0 && upstreamStatuses.every(status => status >= 200 && status < 300),
        no_proxy_errors: proxyErrors.length === 0,
        no_permission_denials: run.permission_denials === 0,
      };
      if (scenario.tools) {
        checks.original_tests_preserved = digest(await readFile(join(dir, 'merge-intervals.test.mjs'), 'utf8')) === digest(TEST_SOURCE);
        // Reinstall the known test before independent verification even if a
        // model unexpectedly changed it. Never execute a modified test file.
        await writeFile(join(dir, 'merge-intervals.test.mjs'), TEST_SOURCE);
        const test = await runCommand(process.execPath, ['--test', 'merge-intervals.test.mjs'], dir);
        checks.independent_tests_pass = test.code === 0;
        checks.read_edit_bash_exercised = ['Read', 'Edit', 'Bash'].every(tool => run.successful_tools.includes(tool));
        checks.tool_continuation_reached_router = routes.some(route => route.tool_result_count > 0);
      }
      if (name === 'thinking_continuation' && !options.simulateJevOutage) {
        checks.first_request_routed_to_opus = family(routes[0]?.model ?? '') === 'opus';
        checks.thinking_history_present = routes.slice(1).some(route => route.thinking_history_count > 0);
        if (config.clientProfile === 'auto') {
          // A new human task may switch between the compatible Auto models
          // while preserving signed thinking; it is not a tool-turn pin.
          checks.auto_thinking_uses_supported_models = routes.every(route => ['sonnet', 'opus'].includes(family(route.model)));
        } else {
          checks.thinking_continuation_pinned = routes.slice(1).some(route => route.reason === 'thinking_history' && family(route.model) === 'opus');
          checks.actual_upstream_stayed_opus = upstreamModels.size > 0 && [...upstreamModels].every(model => family(model) === 'opus');
        }
      }
      if (name === 'large_context') {
        const mainRoutes = routes.filter(route => ['main', 'unspecified'].includes(route.request_class));
        if (config.clientProfile === 'compatible') checks.compatible_client_requested_haiku = mainRoutes.length > 0 && mainRoutes.every(route => family(route.requested_model) === 'haiku');
        checks.large_system_context_reached_router = mainRoutes.some(route => route.system_bytes >= Buffer.byteLength(LARGE_CONTEXT_SYSTEM)
          && route.system_bytes > route.request_bytes * 0.9 && route.messages_bytes < 10000);
        checks.capacity_guard_selected_sonnet = mainRoutes.length > 0 && mainRoutes.every(route => family(route.model) === 'sonnet'
          && (config.clientProfile !== 'compatible' || options.simulateJevOutage || route.reason === 'context_capacity'));
        checks.actual_upstream_used_sonnet = upstreamModels.size > 0 && [...upstreamModels].every(model => family(model) === 'sonnet');
        checks.provider_input_exceeds_haiku_window = usageReports.some(usage => ['input_tokens', 'cache_creation_input_tokens', 'cache_read_input_tokens']
          .reduce((sum, key) => sum + (Number.isSafeInteger(usage[key]) ? usage[key] : 0), 0) > 200000);
      }
      if (scenario.expectedTier && !options.simulateJevOutage) {
        const mainRoutes = routes.filter(route => ['main', 'unspecified'].includes(route.request_class));
        const expectedTier = profileTier(scenario.expectedTier, config.clientProfile);
        checks.expected_tier = mainRoutes.length > 0 && mainRoutes.every(route => family(route.model) === expectedTier);
        checks.actual_expected_model = upstreamModels.size > 0 && [...upstreamModels].every(model => family(model) === expectedTier);
        checks.actual_prompt_reached_classifier = mainRoutes.every(route => route.classifier_contains_example);
        checks.large_reminder_fixture = mainRoutes.every(route => route.context_guard_bytes > 150000);
        if (expectedTier === 'haiku') checks.counted_context_fits_haiku = mainRoutes.every(route => route.context_check === 'within_budget' && route.counted_input_tokens <= 190000);
      }
      if (options.simulateJevOutage) {
        const evaluatedRoutes = routes.filter(route => route.source !== 'passthrough');
        checks.classifier_outage_fell_back = evaluatedRoutes.length > 0 && evaluatedRoutes.every(route => route.source === 'fallback');
        checks.fallback_retained_capability_floor = evaluatedRoutes.every(route => family(route.model) === (family(route.requested_model) === 'opus' ? 'opus' : 'sonnet'));
      }
      const { results, ...safeRun } = run;
      const acceptance = evaluateLiveCase({ checks, routes, evaluator: config.evaluator, expectOutage: options.simulateJevOutage,
        expectedClassifiedTier: scenario.expectedClassifiedTier ?? scenario.expectedTier });
      const item = { case: name, ...acceptance, checks, ...safeRun, routes, request_observations: [...observations.values()],
        upstream_models: [...upstreamModels], upstream_statuses: upstreamStatuses, proxy_errors: proxyErrors,
        classifier_succeeded: routes.some(route => route.source === config.evaluator),
        model_changed: routes.some(route => route.requested_model !== route.model),
        provider_usage: usageReports,
        api_equivalent_savings: Object.values(statusSnapshot?.savings ?? {}),
        status_lines: Object.keys(statusSnapshot?.savings ?? {}).map(session_id => renderStatusLine({ session_id }, statusSnapshot, { color: false, columns: 160 })),
      };
      report.cases.push(item);
      process.stdout.write(`${JSON.stringify({ type: 'case_result', ...item })}\n`);
    }
  } finally { await rm(root, { recursive: true, force: true }); }
  const acceptance = evaluateLiveReport(report.cases, { policy: qualityPolicy, expectOutage: options.simulateJevOutage });
  report.passed = acceptance.passed;
  report.gates = acceptance.gates;
  report.classifier_succeeded = report.cases.every(item => item.classifier_succeeded);
  report.model_changed = report.cases.some(item => item.model_changed);
  process.stdout.write(`${JSON.stringify(report)}\n`);
  if (!report.passed) process.exitCode = 1;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main().catch(() => {
  // Avoid accidentally emitting credentials or provider response bodies.
  process.stderr.write('Live validation could not complete. Check CLI availability, configuration, and --help. No request content or credentials were logged.\n');
  process.exitCode = 1;
});

// Pure acceptance rules shared by the opt-in evaluation harnesses. Thresholds
// are validated before any provider calls; passing transport is not evidence
// of evaluator availability, routing correctness, or completed task quality.
const TIERS = ['haiku', 'sonnet', 'opus'];
const PROFILES = ['compatible', 'native', 'auto'];
const gate = (passed, details = {}) => ({ passed, ...details });
const allPassed = gates => Object.values(gates).every(value => value.passed !== false);

export function modelTier(model) {
  return typeof model === 'string' ? /^claude-(haiku|sonnet|opus)(?:-|$)/.exec(model)?.[1] : undefined;
}

export function profileTier(tier, profile) {
  return profile === 'auto' && tier === 'haiku' ? 'sonnet' : tier;
}

export function parseQualityThreshold(value) {
  if (typeof value !== 'string' || !/^(?:\d+(?:\.\d+)?|\.\d+)$/.test(value)) throw new Error('Quality thresholds must be decimal numbers between 0 and 1');
  const number = Number(value);
  if (!Number.isFinite(number) || number < 0 || number > 1) throw new Error('Quality thresholds must be between 0 and 1');
  return number;
}

export function createEvaluationPolicy({ profile = 'compatible', requiredTiers,
  minAgreement = 1, maxUnderRouteRate = 0 } = {}) {
  if (!PROFILES.includes(profile)) throw new Error('Evaluation profile must be compatible, native, or auto');
  for (const [name, value] of [['minAgreement', minAgreement], ['maxUnderRouteRate', maxUnderRouteRate]]) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0 || value > 1) throw new Error(`${name} must be between 0 and 1`);
  }
  const tiers = requiredTiers ?? (profile === 'native' ? [] : profile === 'auto' ? ['sonnet', 'opus'] : TIERS);
  if (!Array.isArray(tiers) || tiers.some(tier => !TIERS.includes(tier)) || new Set(tiers).size !== tiers.length
    || (profile === 'auto' && tiers.includes('haiku'))) throw new Error('Invalid required tier coverage for evaluation profile');
  return Object.freeze({ profile, minAgreement, maxUnderRouteRate, requiredTiers: Object.freeze([...tiers]) });
}

function evaluatorGate(rows, evaluator, expectOutage) {
  if (!['jev', 'ollama'].includes(evaluator)) throw new Error('Unknown evaluation backend');
  const active = rows.filter(row => row.source !== 'passthrough');
  const fresh = active.filter(row => row.source === evaluator).length;
  const fallbacks = active.filter(row => row.source === 'fallback').length;
  const passed = active.length > 0 && (expectOutage ? fallbacks === active.length
    : fresh > 0 && active.every(row => row.source === evaluator || (row.source === 'cache' && row.evaluator === evaluator)));
  return gate(passed, { expected: expectOutage ? 'fallback' : evaluator, evaluated_requests: active.length,
    successful_evaluations: fresh, fallbacks });
}

export function tierCoverage(tiers, policy) {
  const observed = [...new Set(tiers.filter(tier => TIERS.includes(tier)))].sort();
  const missing = policy.requiredTiers.filter(tier => !observed.includes(tier));
  return gate(missing.length === 0, { required: [...policy.requiredTiers], observed, missing });
}

export function evaluateRoutingReport(rows, { evaluator, policy = createEvaluationPolicy(), classifierOnly = false } = {}) {
  policy = createEvaluationPolicy(policy);
  if (!Array.isArray(rows) || rows.some(row => !row || !TIERS.includes(row.expected))) throw new Error('Invalid evaluation rows');
  const valid = rows.filter(row => TIERS.includes(row.classified_tier)
    && (row.source === evaluator || (row.source === 'cache' && row.evaluator === evaluator)));
  const agreement = rows.length ? valid.filter(row => row.classified_tier === row.expected).length / rows.length : 0;
  const underRoutes = valid.filter(row => TIERS.indexOf(row.classified_tier) < TIERS.indexOf(row.expected)).length;
  const underRouteRate = rows.length ? underRoutes / rows.length : 0;
  const eligibleTiers = valid.map(row => classifierOnly ? row.classified_tier : row.selected_tier ?? modelTier(row.selected_model));
  const gates = {
    transport: gate(null, { reason: 'Claude transport not exercised' }),
    evaluator: evaluatorGate(rows, evaluator, false),
    rubric: gate(rows.length > 0 && valid.length === rows.length && agreement >= policy.minAgreement
      && underRouteRate <= policy.maxUnderRouteRate, { agreement, under_routes: underRoutes, under_route_rate: underRouteRate,
      min_agreement: policy.minAgreement, max_under_route_rate: policy.maxUnderRouteRate }),
    policy: gate(classifierOnly ? null : rows.length > 0 && rows.every(row => {
      const selected = row.selected_tier ?? modelTier(row.selected_model);
      return TIERS.includes(selected) && (policy.profile !== 'auto' || selected !== 'haiku')
        && (row.expected_selected_tier === undefined || selected === row.expected_selected_tier)
        && (row.expected_reason === undefined || row.reason === row.expected_reason);
    }), classifierOnly ? { reason: 'Classifier-only benchmark; routing policy not exercised' } : {}),
    coverage: tierCoverage(eligibleTiers, policy),
    task: gate(null, { reason: 'No Claude task completion measured' }),
  };
  return { schema_version: 1, policy, gates, passed: allPassed(gates), requests: rows.length };
}

const TRANSPORT_CHECKS = new Set(['claude_success', 'requests_reached_router', 'upstream_model_evidence', 'no_upstream_api_errors', 'no_proxy_errors']);
const TASK_CHECKS = new Set(['expected_result', 'original_tests_preserved', 'independent_tests_pass', 'read_edit_bash_exercised']);
function checkGate(checks, names) {
  const selected = Object.fromEntries(Object.entries(checks).filter(([name]) => names.has(name)));
  return gate(Object.keys(selected).length ? Object.values(selected).every(value => value === true) : null, { checks: selected });
}

export function evaluateLiveCase({ checks, routes, evaluator, expectOutage = false, expectedClassifiedTier } = {}) {
  const policyChecks = new Set(Object.keys(checks).filter(name => !TRANSPORT_CHECKS.has(name) && !TASK_CHECKS.has(name)));
  const main = routes.filter(row => ['main', 'unspecified', undefined, ''].includes(row.request_class));
  const labels = main.map(row => expectedClassifiedTier ?? row.expected_classified_tier);
  const rubric = expectOutage ? gate(null, { reason: 'Explicit evaluator outage' })
    : gate(main.length > 0 && labels.every(tier => TIERS.includes(tier))
      && main.every((row, index) => row.classified_tier === labels[index]),
    { expected: expectedClassifiedTier ?? labels, ...(labels.some(tier => !TIERS.includes(tier)) ? { reason: 'Missing declared live classifier label' } : {}) });
  const gates = {
    transport: checkGate(checks, TRANSPORT_CHECKS),
    evaluator: evaluatorGate(routes, evaluator, expectOutage),
    rubric,
    policy: checkGate(checks, policyChecks),
    task: checkGate(checks, TASK_CHECKS),
  };
  // Empty or incomplete harness evidence can never be a successful live case.
  if (!routes.length || gates.transport.passed === null || gates.task.passed === null) gates.transport.passed = false;
  return { gates, passed: allPassed(gates) };
}

export function evaluateLiveReport(cases, { policy = createEvaluationPolicy(), expectOutage = false } = {}) {
  policy = createEvaluationPolicy(policy);
  const tiers = cases.flatMap(item => (item.routes ?? []).filter(row =>
    ['main', 'unspecified', undefined, ''].includes(row.request_class)
      && ['jev', 'ollama', 'cache'].includes(row.source)).map(row => modelTier(row.model)));
  const coverage = expectOutage ? gate(null, { reason: 'Explicit evaluator outage' }) : tierCoverage(tiers, policy);
  return { policy, gates: { coverage }, passed: cases.length > 0 && cases.every(item => item.passed === true) && coverage.passed !== false };
}

